namespace FableGameWorkspaceNamespace.Client

open Browser.Types
open FS.GG.Game.Render
open FS.GG.Game.Render.Browser
open FS.GG.UI.Scene
open FS.GG.Game.Core

/// The SVG, Pixi and Babylon renderers of `App.Model`, generated by scripts/new-game-renderers.sh
/// (FS.GG.Game, GAME-RENDER-ADOPT-01.1). Edit freely: `view`, `objects` and `select` are game-specific. Walkthrough:
/// src/Game.Render/README.md, "Three-adapter authoring path" and "Interaction contract".
///
/// The game is played by selecting a cell of the arena, on every backend: a pointer press on a cell, the keyboard
/// (arrows, Enter or Space, Escape) and the accessible mirror (one labelled button per cell) all ask the game to
/// select a cell through `interaction`. `Stage.fs` answers each request with the same `CellClicked` message the DOM
/// grid dispatches, so the server stays the only authority for movement.
module Renderers =

    /// The Scene size in pixels, shared by the SVG root and both canvases.
    let width = 400.0
    let height = 240.0

    let private rgb red green blue : Color =
        {
            Red = red
            Green = green
            Blue = blue
            Alpha = 255uy
        }

    /// The colours of `index.html`'s `.cell` classes, so the three backends match the DOM grid.
    let backgroundColor = rgb 16uy 19uy 26uy
    let arenaColor = rgb 40uy 46uy 60uy
    let selfColor = rgb 63uy 167uy 255uy
    let otherColor = rgb 255uy 112uy 67uy
    let previewColor = rgb 255uy 213uy 79uy
    /// The colour of the square drawn behind the selected cell.
    let selectionColor = rgb 255uy 140uy 0uy

    /// The side of one arena cell in pixels: the whole arena fits the scene, whatever size the server reports.
    let cellSize (state: App.Model) : float =
        if state.ArenaWidth > 0 && state.ArenaHeight > 0 then
            min (width / float state.ArenaWidth) (height / float state.ArenaHeight)
        else
            0.0

    let private cellOrigin (size: float) (cell: Cell) : float * float =
        float cell.Col * size, float cell.Row * size

    /// The shared Scene description of the state: every backend draws exactly this. The canvas backends draw
    /// `Rectangle`, `FilledEllipse` and `Circle` (later nodes on top) and treat `Group`, `Translate` and `Empty` as
    /// structure; any other node is counted as unsupported and skipped, so keep the view to those.
    ///
    /// The arena is one rectangle, the selected path (`PreviewPath`) is a rectangle per cell, every other player is a
    /// rectangle and this client's own player is a circle. The server stays the authority: the view only draws the
    /// `Players` it was told about.
    let view (state: App.Model) : Scene =
        let size = cellSize state

        let arena =
            if size > 0.0 then
                [
                    SceneNode.Rectangle(
                        (0.0, 0.0, size * float state.ArenaWidth, size * float state.ArenaHeight),
                        arenaColor
                    )
                ]
            else
                []

        let selected =
            match state.Selected with
            | Some cell when size > 0.0 ->
                let x, y = cellOrigin size cell
                [ SceneNode.Rectangle((x + 2.0, y + 2.0, size - 4.0, size - 4.0), selectionColor) ]
            | _ -> []

        let path =
            state.PreviewPath
            |> List.map (fun cell ->
                let x, y = cellOrigin size cell
                SceneNode.Rectangle((x + 1.0, y + 1.0, size - 2.0, size - 2.0), previewColor))

        let others =
            state.Players
            |> Map.toList
            |> List.filter (fun (id, _) -> Some id <> state.PlayerId)
            |> List.map (fun (_, cell) ->
                let x, y = cellOrigin size cell
                SceneNode.Rectangle((x + 4.0, y + 4.0, size - 8.0, size - 8.0), otherColor))

        let self =
            state.PlayerId
            |> Option.bind (fun id -> Map.tryFind id state.Players)
            |> Option.map (fun cell ->
                let x, y = cellOrigin size cell
                SceneNode.Circle({ X = x + size / 2.0; Y = y + size / 2.0 }, size / 2.0 - 3.0, selfColor))
            |> Option.toList

        {
            Nodes =
                [
                    SceneNode.Rectangle((0.0, 0.0, width, height), backgroundColor)
                    yield! arena
                    yield! selected
                    yield! path
                    yield! others
                    yield! self
                ]
        }

    /// The id of a cell as a selectable object, and back. `"col-row"`, as the DOM grid's `data-cell` attribute.
    let cellId (cell: Cell) : string = sprintf "%d-%d" cell.Col cell.Row

    let tryCell (id: string) : Cell option =
        match id.Split '-' with
        | [| col; row |] ->
            match System.Int32.TryParse col, System.Int32.TryParse row with
            | (true, c), (true, r) -> Some { Col = c; Row = r }
            | _ -> None
        | _ -> None

    /// What a cell holds, in the words the DOM grid's `aria-label` uses.
    let private holder (state: App.Model) (cell: Cell) : string =
        match state.Players |> Map.tryFindKey (fun _ c -> c = cell) with
        | Some id when Some id = state.PlayerId -> "you"
        | Some _ -> "another player"
        | None -> "empty"

    /// The selectable objects of a state: one per arena cell, in row-major order (the order of the keyboard focus and
    /// of the accessible mirror), each the square the Scene draws the cell in. Nothing before the arena is known.
    let objects (state: App.Model) : SelectableObject list =
        let size = cellSize state

        if size <= 0.0 then
            []
        else
            [
                for row in 0 .. state.ArenaHeight - 1 do
                    for col in 0 .. state.ArenaWidth - 1 do
                        let cell: Cell = { Col = col; Row = row }
                        let x, y = cellOrigin size cell

                        yield
                            {
                                Id = cellId cell
                                Label = sprintf "Column %d, row %d: %s" (col + 1) (row + 1) (holder state cell)
                                Bounds = { X = x; Y = y; Width = size; Height = size }
                                Shape = SelectableShape.Box
                            }
            ]

    /// The game's own selection rule, applied by the kit and by `Stage.fs`: a cell of the arena becomes the selection,
    /// `Clear` empties it, and a request for an id the state does not have changes nothing.
    let select (request: SelectionRequest) (state: App.Model) : App.Model =
        match request with
        | SelectionRequest.Clear -> { state with Selected = None }
        | SelectionRequest.Select id ->
            match tryCell id with
            | Some cell when objects state |> List.exists (fun target -> target.Id = id) -> { state with Selected = Some cell }
            | _ -> state

    /// The game's interaction: selecting a cell on any backend.
    let interaction: SceneInteraction<App.Model> =
        SceneInteraction.create objects (fun state -> state.Selected |> Option.map cellId) select

    /// The renderer declaration: SVG, Pixi and Babylon in `container`, Pixi's late failures on `route`, and the game played
    /// by selection on every backend: each backend's input host reports its `SelectionRequest` to `selection`. Give a
    /// backend its own representation with `|> SceneRenderers.withView RendererBackend.Babylon babylonView`.
    let declare
        (container: HTMLElement)
        (route: LateFailureRoute)
        (selection: SelectionRoute)
        (interaction: SceneInteraction<App.Model>)
        : SceneRenderers<App.Model> =
        BrowserRenderers.declare container (BrowserRenderers.options "Arena" width height) route view
        |> SceneRenderers.withInteraction interaction selection

    /// Start rendering `initial` in `container` on SVG. Switch at runtime with
    /// `driver.Dispatch(RendererMsg.SelectBackend backend)`, present a new state with
    /// `driver.Dispatch(RendererMsg.StateChanged state)`, and offer `RendererSelection.available driver.Model`. Bind
    /// `selection` to the game (`SelectionRoute.bind`) to hear the player's requests.
    let start
        (container: HTMLElement)
        (initial: App.Model)
        (selection: SelectionRoute)
        (onChange: RendererModel<App.Model> -> unit)
        : RendererDriver<App.Model> =
        let route = BrowserRenderers.route ()
        BrowserRenderers.start route (SceneRenderers.registry (declare container route selection interaction)) initial onChange

    /// The conformance subject for these renderers, for a browser test: call
    /// `BrowserConformance.installContextProbe ()` first, then `RendererConformance.run`, and require
    /// `RendererConformance.failures` to be empty. `states` are at least two distinct game states that look different;
    /// `shows` reads a backend's output back (the SVG DOM, or a pixel through `BrowserConformance.readPixel`) and must
    /// reject a state that is not shown. Pixi's adapter late failure is exercised through its own report. The subject
    /// includes the kit's `interaction` section for `interaction` (real pointer and keyboard input through the test
    /// driver's `window.__fsggInput`).
    let conformance
        (container: HTMLElement)
        (interaction: SceneInteraction<App.Model>)
        (states: App.Model list)
        (shows: ConformanceHost<App.Model> -> RendererBackend -> App.Model -> Async<Result<unit, string>>)
        : ConformanceSubject<App.Model> =
        let route = BrowserRenderers.route ()
        let selection = SelectionRoute.create ()

        BrowserConformance.subject
            container
            route
            (SceneRenderers.registry (declare container route selection interaction))
            RendererBackend.all
            states
            shows
        |> RendererConformance.withInteraction interaction selection (BrowserConformance.interactionProbe container)
